function ilv($d,$key){
  if($key==='image_urls'){
    $v=$d['image_urls']??($d['images']??[]); return is_array($v)?json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE):(string)$v;
  }
  if($key==='offer_title') return (string)($d['offer_title']??($d['title']??''));
  if($key==='offer_amount') return (string)($d['offer_amount']??($d['amount']??''));
  if($key==='offer_unit') return (string)($d['offer_unit']??($d['unit']??''));
  $v=$d[$key]??''; return is_array($v)?json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE):(string)$v;
}
