<script>
(function(){
  const root=document.getElementById('il-game-select');
  if(!root)return;
  const btn=document.getElementById('il-game-btn');
  const menu=document.getElementById('il-game-menu');
  const search=document.getElementById('il-game-search');
  const value=document.getElementById('il-game-value');
  const label=document.getElementById('il-game-label');
  const empty=document.getElementById('il-game-empty');
  function filter(){
    const q=(search?.value||'').trim().toLowerCase();let visible=0;
    menu.querySelectorAll('.il-game-option').forEach(opt=>{const show=!q||((opt.dataset.label||'')+' '+(opt.dataset.value||'')).toLowerCase().includes(q);opt.style.display=show?'':'none';if(show)visible++;});
    if(empty)empty.style.display=visible?'none':'block';
  }
  btn?.addEventListener('click',e=>{e.stopPropagation();menu.classList.toggle('open');if(menu.classList.contains('open')){if(search)search.value='';filter();setTimeout(()=>search?.focus(),0);}});
  search?.addEventListener('click',e=>e.stopPropagation());search?.addEventListener('input',filter);
  menu.querySelectorAll('.il-game-option').forEach(opt=>opt.addEventListener('click',()=>{value.value=opt.dataset.value;label.textContent=opt.dataset.label;const next=opt.querySelector('img'),cur=btn.querySelector('img');if(next&&cur)cur.src=next.src;menu.querySelectorAll('.il-game-option').forEach(x=>x.classList.remove('active'));opt.classList.add('active');menu.classList.remove('open');}));
  document.addEventListener('click',e=>{if(!e.target.closest('#il-game-select'))menu.classList.remove('open');});
})();
</script>
