<div class="modal fade" id="json-format" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered modal-lg"><div class="modal-content"><div class="modal-header"><h5 class="modal-title"><i class="fa-duotone fa-code me-2"></i><?= strtolower($isTopup ? 'topups' : 'items') ?>.json format</h5><button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><div class="modal-body"><pre class="ia-code"><code><?= esc($sampleJson) ?></code></pre></div><div class="modal-footer"><button type="button" class="ia-modal-close-btn" data-bs-dismiss="modal"><i class="fa-regular fa-xmark"></i> Close</button><button type="button" class="btn btn-primary" id="downloadSample"><i class="fa-regular fa-download me-1"></i>Download sample</button></div></div></div></div>
<div class="modal fade" id="listing-import-confirm" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered ia-confirm-dialog"><div class="modal-content ia-confirm-content"><div class="ia-confirm-body"><div class="ia-confirm-icon"><i class="fa-regular fa-cloud-arrow-up"></i></div><div><h5 class="ia-confirm-title">Start import?</h5><p class="ia-confirm-text">All staged <?= strtolower($label) ?> will be imported into your shop. After the import is finished, you will be redirected automatically.</p></div></div><div class="ia-confirm-footer"><button type="button" class="ia-confirm-cancel" data-bs-dismiss="modal"><i class="fa-regular fa-xmark"></i> Cancel</button><button type="button" class="ia-confirm-submit" id="confirmListingImport"><i class="fa-regular fa-cloud-arrow-up"></i> Import <?= $label ?></button></div></div></div></div>
<script>
(function(){
 const unsaved=document.getElementById('unsaved');
 document.querySelectorAll('.il-value').forEach(el=>el.addEventListener('input',()=>{el.classList.add('dirty');unsaved?.classList.add('show')}));
 document.getElementById('saveRows')?.addEventListener('click',async function(){
   const rows=[]; document.querySelectorAll('#editTable tbody tr[data-row-id]').forEach(tr=>{const data={};tr.querySelectorAll('.il-value').forEach(el=>{let v=el.value;if(el.dataset.field==='image_urls'){try{v=JSON.parse(v)}catch(e){v=v.split(',').map(x=>x.trim()).filter(Boolean)}}data[el.dataset.field]=v});rows.push({id:Number(tr.dataset.rowId),data})});
   const fd=new FormData();fd.append('action','seller_listing_import_save_rows');fd.append('entity','<?= $entity ?>');fd.append('batch_id','<?= (int)$batch['id'] ?>');fd.append('rows',JSON.stringify(rows));
   const res=await fetch('<?= AJAX_URL ?>',{method:'POST',body:fd,credentials:'same-origin'}); const out=await res.json(); if(out.sendToast && window.Swal) Swal.fire({toast:true,position:'top-end',timer:2500,showConfirmButton:false,icon:out.sendToast.type==='danger'?'error':'success',title:out.sendToast.message}); document.querySelectorAll('.dirty').forEach(x=>x.classList.remove('dirty'));unsaved?.classList.remove('show');
 });
 document.getElementById('deleteBatch')?.addEventListener('click',()=>{if(confirm('Delete this import and all staged rows?'))document.getElementById('deleteForm').requestSubmit()});
 const fmtSize=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB';
 const input=document.getElementById('listing-json-input'),row=document.getElementById('listing-file-row'),name=document.getElementById('listing-file-name'),size=document.getElementById('listing-file-size'),remove=document.getElementById('listing-file-remove'),submit=document.getElementById('listing-import-submit');
 input?.addEventListener('change',()=>{const f=input.files?.[0];if(!f)return;name.textContent=f.name;size.textContent=fmtSize(f.size);row.classList.add('show');submit.disabled=false});
 remove?.addEventListener('click',()=>{input.value='';row.classList.remove('show');submit.disabled=true});
 const download=(text,file)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=file;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)};
 document.getElementById('downloadSample')?.addEventListener('click',()=>download(<?= json_encode($sampleJson) ?>,'lolboost-<?= $isTopup ? 'topups' : 'items' ?>-import-sample.json'));
 document.getElementById('downloadCurrent')?.addEventListener('click',()=>{const data=[];document.querySelectorAll('#editTable tbody tr[data-row-id]').forEach(tr=>{const d={};tr.querySelectorAll('.il-value').forEach(el=>d[el.dataset.field]=el.value);data.push(d)});download(JSON.stringify({<?= $isTopup ? 'topups' : 'items' ?>:data},null,2),'lolboost-<?= $isTopup ? 'topups' : 'items' ?>-import.json')});
 document.getElementById('openImportConfirm')?.addEventListener('click',()=>bootstrap.Modal.getOrCreateInstance(document.getElementById('listing-import-confirm')).show());
 document.getElementById('confirmListingImport')?.addEventListener('click',()=>{bootstrap.Modal.getOrCreateInstance(document.getElementById('listing-import-confirm')).hide();document.getElementById('runImport').requestSubmit()});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();document.getElementById('saveRows')?.click()}});
})();
</script>
<?php endif; ?>
